-- Lion Patrol v2 — Karim feedback (Oct 25, 2026). Re-runnable; touches patrol_ objects only; never deletes incidents.
-- 1. Patrol start/end are daily-log entries, not incidents: "Patrol & Shift" leaves the incident categories.
-- 5. Shift notes / relief-handoff / post check / checkpoint note become "Shift Log" daily-log (DAR) types.
begin;

-- Defaults for new orgs (same JSON as 20261024000500_patrol_seed.sql, regenerated by scripts/gen-seed-sql.mjs).
create or replace function public.patrol_default_categories()
returns jsonb language sql immutable set search_path = public as $seed$
  select '[{"name":"Shift Log","color":"#C9A23F","icon":"shield","use_for":"dar","default_severity":"low","required_fields":[],"fields":[],"subtypes":["Shift notes","Relief / handoff","Post check","Checkpoint note"]},{"name":"Access & Doors","color":"#4F7CC4","icon":"door","use_for":"both","default_severity":"low","required_fields":[],"subtypes":["Door/gate found open","Door/gate unsecured","Lock-up completed","Unlock","Key/fob issue"],"fields":[]},{"name":"Alarm Response","color":"#C66B3D","icon":"bell","use_for":"both","default_severity":"medium","required_fields":[],"subtypes":["Intrusion alarm","Fire alarm panel","Panic alarm","False alarm","Alarm reset"],"fields":[]},{"name":"Suspicious Activity","color":"#C98A2E","icon":"eye","use_for":"both","default_severity":"medium","required_fields":[],"subtypes":["Suspicious person","Suspicious vehicle","Loitering","Suspicious package"],"fields":["people","vehicles","police"]},{"name":"Trespass & Removal","color":"#B85C7A","icon":"user-x","use_for":"incident","default_severity":"medium","required_fields":["people"],"subtypes":["Trespass warning issued","Person removed","Trespass notice served","Returned after warning"],"fields":["people","vehicles","police"]},{"name":"Theft & Shoplifting","color":"#C0504D","icon":"bag","use_for":"incident","default_severity":"high","required_fields":["people","property_damage"],"subtypes":["Shoplifting","Theft from vehicle","Package theft","Burglary","Attempted theft"],"fields":["people","vehicles","police"]},{"name":"Vandalism, Graffiti & Damage","color":"#8467B5","icon":"spray","use_for":"incident","default_severity":"medium","required_fields":["property_damage","photos"],"subtypes":["Graffiti","Broken window/glass","Property damage","Vehicle damage"],"fields":["people","vehicles","police"]},{"name":"Disturbance & Noise","color":"#5F6BC2","icon":"volume","use_for":"both","default_severity":"medium","required_fields":["people"],"subtypes":["Noise complaint","Verbal dispute","Fight/assault","Intoxicated person"],"fields":["people","vehicles","police"]},{"name":"Medical & Injury","color":"#C0504D","icon":"medical","use_for":"incident","default_severity":"high","required_fields":["injury","people"],"subtypes":["Injury","Illness","Fall","Overdose suspected","EMS requested"],"fields":["police"]},{"name":"Fire, Safety & Hazard","color":"#C66B3D","icon":"flame","use_for":"both","default_severity":"high","required_fields":["photos"],"subtypes":["Smoke/fire","Spill","Trip hazard","Gas odor","Blocked exit"],"fields":[]},{"name":"Maintenance & Facility","color":"#3F94B0","icon":"wrench","use_for":"both","default_severity":"low","required_fields":[],"subtypes":["Lights out","Water leak","Elevator issue","HVAC issue","Broken fixture"],"fields":[]},{"name":"Parking & Vehicles","color":"#4F7CC4","icon":"car","use_for":"both","default_severity":"low","required_fields":["vehicles"],"subtypes":["Parking violation","Tow requested","Abandoned vehicle","Blocked fire lane"],"fields":["vehicles"]},{"name":"Police, Fire & EMS Contact","color":"#5F6BC2","icon":"siren","use_for":"incident","default_severity":"high","required_fields":["police"],"subtypes":["Police called","Police on site","Fire dept on site","EMS on site"],"fields":["people","vehicles","police"]},{"name":"Client / Resident Request","color":"#3E9C8F","icon":"user","use_for":"both","default_severity":"low","required_fields":[],"subtypes":["Escort","Lockout assist","Information","Complaint"],"fields":[]},{"name":"Package & Delivery","color":"#C98A2E","icon":"package","use_for":"both","default_severity":"low","required_fields":[],"subtypes":["Delivery received","Package left unsecured","Delivery issue"],"fields":[]},{"name":"Welfare Check (Unhoused Persons)","color":"#3E9C8F","icon":"heart","use_for":"both","default_severity":"low","required_fields":[],"subtypes":["Welfare check","Encampment observed","Resources offered","Asked to relocate"],"fields":[]},{"name":"Drug Activity / Paraphernalia","color":"#8467B5","icon":"pill","use_for":"incident","default_severity":"medium","required_fields":["photos"],"subtypes":["Suspected drug activity","Needles/paraphernalia found"],"fields":[]},{"name":"Animal","color":"#4E9F5D","icon":"paw","use_for":"both","default_severity":"low","required_fields":[],"subtypes":["Stray animal","Aggressive animal","Animal control called"],"fields":[]},{"name":"Lost & Found","color":"#3F94B0","icon":"search","use_for":"both","default_severity":"low","required_fields":[],"subtypes":["Item found","Item reported lost","Item returned"],"fields":[]},{"name":"Weather","color":"#64748B","icon":"cloud","use_for":"both","default_severity":"low","required_fields":[],"subtypes":["Storm damage","Ice/snow hazard","Flooding","Power outage"],"fields":[]},{"name":"Retail Operations","color":"#C9A23F","icon":"store","use_for":"dar","default_severity":"low","required_fields":[],"subtypes":["Store open check","Store close check","Cash/vault escort","Customer assist"],"fields":[]},{"name":"Residential (Apartments)","color":"#4E9F5D","icon":"building","use_for":"dar","default_severity":"low","required_fields":[],"subtypes":["Amenity check (pool/gym)","Mailroom check","Unit door open","Move-in/out observed"],"fields":[]},{"name":"Safety Equipment","color":"#C66B3D","icon":"extinguisher","use_for":"both","default_severity":"low","required_fields":[],"subtypes":["Fire extinguisher check","Exit sign out","AED check","Camera not working"],"fields":[]},{"name":"Other","color":"#64748B","icon":"note","use_for":"both","default_severity":"low","required_fields":[],"subtypes":["General observation","Other"],"fields":[]}]'::jsonb
$seed$;

-- "Shift Log" (daily log only) for every existing org, listed first among log categories.
insert into public.patrol_categories (org_id, name, color, icon, sort, required_fields, default_severity, use_for)
select o.id, 'Shift Log', '#C9A23F', 'shield', -1, '{}', 'low', 'dar'
  from public.patrol_orgs o
 where not exists (select 1 from public.patrol_categories c where c.org_id = o.id and lower(c.name) = 'shift log');

insert into public.patrol_subtypes (org_id, category_id, name, sort)
select c.org_id, c.id, s.name, s.ord - 1
  from public.patrol_categories c
 cross join unnest(array['Shift notes', 'Relief / handoff', 'Post check', 'Checkpoint note']) with ordinality as s(name, ord)
 where lower(c.name) = 'shift log'
on conflict do nothing;

-- "Patrol & Shift": delete subtypes/categories nothing references; hide the rest (history stays intact).
delete from public.patrol_subtypes s
 using public.patrol_categories c
 where s.category_id = c.id and lower(c.name) = 'patrol & shift'
   and not exists (select 1 from public.patrol_incidents i where i.subtype_id = s.id)
   and not exists (select 1 from public.patrol_dar_entries e where e.subtype_id = s.id);

update public.patrol_subtypes s set hidden = true
  from public.patrol_categories c
 where s.category_id = c.id and lower(c.name) = 'patrol & shift' and not s.hidden;

delete from public.patrol_categories c
 where lower(c.name) = 'patrol & shift'
   and not exists (select 1 from public.patrol_incidents i where i.category_id = c.id)
   and not exists (select 1 from public.patrol_dar_entries e where e.category_id = c.id)
   and not exists (select 1 from public.patrol_subtypes s where s.category_id = c.id);

update public.patrol_categories set hidden = true
 where lower(name) = 'patrol & shift' and not hidden;

commit;
